SELECT * FROM (
    SELECT * FROM ANS_BREAKING_NEWS WHERE TITLE LIKE CONCAT('%', #{keyword}, '%') 
    UNION 
    SELECT * FROM ANS_MAIN_NEWS WHERE TITLE LIKE CONCAT('%', #{keyword}, '%')
) AS search_results 
LIMIT #{pageSize} OFFSET #{offset}

SELECT TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_MAIN_NEWS 
WHERE idx=#{idx}

SELECT TITLE, SMR, PRESS, IMG_URL1, URL
FROM ANS_BREAKING_NEWS  
WHERE idx=#{idx}

SELECT smr FROM ANS_MAIN_NEWS
UNION ALL
SELECT smr FROM ANS_BREAKING_NEWS;
